from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


class Group:
    def __init__(self, members: list[str]) -> None:
        if len(set(members)) != len(members):
            raise ValueError("Group members must be unique")
        self._members = list(members)
        self._balances = {member: 0 for member in members}

    def add_expense(
        self,
        payer: str,
        amount: float,
        participants: list[str] | None = None,
    ) -> None:
        if payer not in self._balances:
            raise ValueError("Payer is not a group member")

        participants = self._members if participants is None else participants
        if not participants:
            raise ValueError("An expense must have at least one participant")
        if len(set(participants)) != len(participants):
            raise ValueError("Participants must be unique")
        if any(member not in self._balances for member in participants):
            raise ValueError("Participant is not a group member")

        try:
            value = Decimal(str(amount))
            if not value.is_finite() or value < 0:
                raise ValueError("Amount must be finite and non-negative")
            cents = int((value * 100).to_integral_value(rounding=ROUND_HALF_UP))
        except (InvalidOperation, OverflowError) as exc:
            raise ValueError("Invalid amount") from exc

        share = cents // len(participants)
        for member in participants:
            if member != payer:
                self._balances[member] -= share
                self._balances[payer] += share

    def balances(self) -> dict[str, float]:
        return {member: cents / 100 for member, cents in self._balances.items()}

    def settle_up(self) -> list[tuple[str, str, float]]:
        debtors = sorted(
            [(member, -cents) for member, cents in self._balances.items()
             if cents <= -100],
            key=lambda item: item[1],
            reverse=True,
        )
        creditors = sorted(
            [(member, cents) for member, cents in self._balances.items()
             if cents >= 100],
            key=lambda item: item[1],
            reverse=True,
        )

        payments = []
        i = j = 0
        while i < len(debtors) and j < len(creditors):
            debtor, debt = debtors[i]
            creditor, credit = creditors[j]
            amount = min(debt, credit)
            payments.append((debtor, creditor, amount / 100))

            debt -= amount
            credit -= amount
            if debt < 100:
                i += 1
            else:
                debtors[i] = (debtor, debt)
            if credit < 100:
                j += 1
            else:
                creditors[j] = (creditor, credit)

        return payments
